/* ==UserStyle==
@name           Arch Linux Dark
@namespace      github.com/aruncveli/userstyles
@version 26.8.5
@description    Dark theme for the Arch Linux website
@author         Arun Chandanaveli <aruncveli@gmail.com> (https://github.com/aruncveli)
@homepageURL    https://github.com/aruncveli/userstyles
@supportURL     https://github.com/aruncveli/userstyles/issues
@license        MIT
@preprocessor   default
@var color fg "Foreground" #fff
@var color fg1 "Foreground darkened 1" #bbb
@var color bg "Background" #000
@var color bg1 "Background lightened 1" #111
@var color bg2 "Background lightened 2" #222
@var color bg3 "Background lightened 3" #333
@var color link-color "Link" #5cb8ff
@var color red-color "Red" #ff6165
@var text font-size "Font size" 0.95em
@var text font-size-forum "Forum font size" 1.2em
==/UserStyle== */

@-moz-document url-prefix("https://archlinux.org"), url-prefix("https://aur.archlinux.org"), url-prefix("https://security.archlinux.org") {
  :root {
    color-scheme: dark;
  }

  a {
    &:link,
    &:hover,
    &:visited,
    &:visited:hover {
      color: var(--link-color);
    }
  }

  body {
    color: var(--fg);
    background-color: var(--bg);
  }

  table.styled-table {
    border-color: var(--bg);
    background-color: var(--bg);
    th {
      border-bottom-color: var(--bg1);
    }
    tr td {
      border-top-color: var(--bg);
    }
    th,
    tr:hover {
      background-color: var(--bg1);
    }
  }

  code {
    text-wrap: wrap;
  }
}

@-moz-document url-prefix("https://archlinux.org"), url-prefix("https://aur.archlinux.org") {
  dl dt,
  #pkgsearch input,
  .pkgsearch-typeahead li a {
    color: var(--fg);
  }

  div.box {
    border-color: var(--bg1);
    border-radius: 16px;
  }

  div.box,
  code,
  pre,
  #pkgsearch,
  #news h3 a {
    background-color: var(--bg1);
  }

  #news h3 a,
  pre,
  #pkgsearch {
    border-color: var(--bg1);
    border-radius: 16px;
  }

  #pkgsearch input {
    background-color: var(--bg);
    border-color: var(--bg);
  }

  .pkgsearch-typeahead {
    background-color: var(--bg2);
    border-color: var(--bg2);
  }

  #pkgsearch input,
  .pkgsearch-typeahead {
    border-radius: 4px;
  }

  h3 span.arrow {
    border-top-color: var(--bg1);
  }

  dl {
    dt,
    dd {
      border-top-color: var(--bg);
    }
  }

  h2 {
    border-bottom-color: var(--bg1);
  }

  #news h4 {
    border-bottom-color: var(--bg);
  }

  table.results {
    border-top-color: var(--bg1);
    border-bottom-color: var(--bg1);
  }

  .results {
    th {
      background-color: var(--bg);
      border-bottom-color: var(--bg);
    }

    tr:nth-child(odd of :not([hidden])),
    tr:nth-child(even of :not([hidden])) {
      background-color: var(--bg1);
    }
  }

  table thead {
    th.tablesorter-headerAsc,
    th.tablesorter-headerDesc {
      background-color: var(--bg);
    }
  }

  #content {
    font-size: var(--font-size);
  }
}

@-moz-document url-prefix("https://archlinux.org/packages"), url-prefix("https://aur.archlinux.org/packages"), url-prefix("https://aur.archlinux.org/pkgbase") {
  #pkglist-results tr:hover,
  #pkgdetails #metadata h3,
  #pkgdetails #detailslinks > div {
    background-color: var(--bg);
  }

  #pkgdetails {
    #metadata h3,
    #detailslinks > div {
      border-color: var(--bg);
    }

    #metadata h3 {
      border-radius: 4px;
    }

    #detailslinks > div {
      border-radius: 12px;
    }

    #actionlist .flagged {
      color: var(--red-color);
    }
  }
  .comment-header {
    border-bottom-color: var(--bg);
  }
}

@-moz-document url-prefix("https://aur.archlinux.org") {
  form.link button,
  #archdev-navbar li a {
    color: var(--link-color);
  }
}

@-moz-document url-prefix("https://aur.archlinux.org/packages"), url-prefix("https://aur.archlinux.org/packages") {
  .text-button,
  .text-button:hover {
    color: var(--link-color);
  }

  .flagged a {
    color: var(--red-color);
  }

  .comments-header h3 span.text {
    background-color: var(--bg1);
    border-color: var(--bg1);
    border-radius: 16px;
  }

  .edited {
    color: var(--fg);
  }
}

