@-moz-document url-prefix("https://archlinux.org/groups") {
  .results {
    tr:nth-child(odd),
    tr:nth-child(even) {
      background-color: var(--bg1);
    }

    th {
      &,
      &.tablesorter-headerAsc,
      &.tablesorter-headerDesc {
        background-color: var(--bg);
      }
    }
  }
}

@-moz-document url-prefix("https://archlinux.org/todo") {
  #dev-todo-lists,
  #dev-todo-pkglist {
    tr:hover {
      background-color: var(--bg);
    }
  }

  .todo-info {
    color: var(--fg);
    border-bottom-color: var(--bg1);
  }

  .todo-pkgbases {
    border-top-color: var(--bg1);
  }
}

@-moz-document url-prefix("https://archlinux.org/news") {
  .results tr:nth-child(odd of :not([hidden])),
  #article-list tr:nth-child(odd),
  .results tr:nth-child(even of :not([hidden])),
  #article-list tr:nth-child(even) {
    background-color: var(--bg1);
  }

  div.news-article .article-info {
    color: var(--fg);
  }
}

@-moz-document url-prefix("https://archlinux.org/download") {
  #arch-downloads h3 {
    border-bottom-color: var(--bg1);
  }
}

@-moz-document url-prefix("https://security.archlinux.org") {
  hr {
    border-top-color: var(--bg);
  }
}

@-moz-document url-prefix("https://archlinux.org/people") {
  .arch-bio-entry {
    table.bio th {
      color: var(--fg1);
    }
    td {
      h3 {
        border-bottom-color: var(--bg1);
      }
      &.pic img {
        border-color: var(--bg1);
      }
    }
  }
}

@-moz-document url-prefix("https://archlinux.org/master-keys"), url-prefix("https://archlinux.org/feeds") {
  table.pretty2,
  .pretty2 td {
    border-color: var(--bg1);
  }

  .pretty2 th {
    background-color: var(--bg);
    border-color: var(--bg);
  }
}

@-moz-document domain("bbs.archlinux.org") {
  :root {
    color-scheme: dark;
  }

  .pun .punwrap {
    font-size: var(--font-size-forum);
  }

  .pun,
  .pun .punwrap,
  .pun label,
  .pun .blocktable th,
  #punindex .blocktable h2,
  .pun .postmsg,
  .pun .blockpost h2,
  .pun .codebox,
  .pun .quotebox,
  .pun .postmsg .postedit,
  .pun #quickpost h2,
  .pun .quotebox cite,
  .pun legend,
  #punpost .blockform h2,
  #punedit .blockform h2 {
    color: var(--fg);
  }

  .pun a,
  .pun a:link,
  #brdmain a:visited,
  #brdmenu a,
  #brdmenu a:link,
  #brdmenu a:visited {
    color: var(--link-color);
  }

  html,
  .pun,
  .pun .punwrap,
  #brdmenu,
  #brdmenu a,
  #brdmenu a:link,
  #brdmenu a:visited,
  .pun .blocktable .box,
  .pun .blocktable th,
  .pun .blockpost,
  .pun .blockpost .postbody,
  .pun .blockpost .postfoot,
  .pun .postmsg hr,
  #postpreview {
    background-color: var(--bg);
  }

  .pun .codebox,
  .pun .quotebox,
  .pun .blockpost h2,
  .pun .blockform .box,
  .pun #quickpost h2,
  .pun .infldset,
  #punpost .blockform h2,
  #punedit .blockform h2 {
    background-color: var(--bg1);
  }

  .pun .punwrap,
  #brdmenu a,
  #brdmenu a:link,
  #brdmenu a:visited,
  #brdmain,
  .pun .blocktable .box,
  .pun .blocktable td,
  #brdstats,
  #brdstats #onlinelist,
  .pun .linkst .crumbsplus .pagepost,
  .pun .blockpost,
  .pun .blockpost h2,
  #quickpost,
  .pun .blockform .box,
  .pun .blockpost .postbody,
  .pun .blockpost .postfoot,
  .pun .postlinksb .crumbsplus .pagepost,
  #postpreview {
    border-color: var(--bg);
  }

  .pun .infldset,
  .pun .quotebox,
  .pun .codebox {
    border-color: var(--bg1);
  }
}
@-moz-document url-prefix("https://bbs.archlinux.org/profile.php") {
  .pun .blockmenu .isactive a:visited,
  .pun a:hover,
  #brdmain a:hover {
    background-color: var(--bg1);
  }

  .pun .blockmenu ul,
  .pun .blockmenu li {
    border-color: var(--bg);
  }
}

@-moz-document url-prefix("https://bbs.archlinux.org/misc.php") {
  #punmisc #rules .box {
    background-color: var(--bg);
    border-color: var(--bg);
  }
}

@-moz-document url-prefix("https://bbs.archlinux.org/userlist.php") {
  .pun #users1 h2 {
    background-color: var(--bg1);
  }
}

@-moz-document url-prefix("https://bbs.archlinux.org/search.php") {
  .pun .checklist {
    background-color: var(--bg2);
    border-color: var(--bg1);
  }
}
